"""Loading CSV files into tables for minisql."""

import csv
import os
import re

from .errors import QueryError

_INTEGER = re.compile(r"-?[0-9]+\Z")
_DECIMAL = re.compile(r"(?:-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+)\Z")


class Table:
    """A loaded CSV file: ``headers`` is a list of names, ``rows`` tuples."""

    def __init__(self, headers, rows):
        self.headers = list(headers)
        self.rows = [tuple(row) for row in rows]

    def __repr__(self):  # pragma: no cover - debugging convenience
        return "Table(headers=%r, rows=%r)" % (self.headers, self.rows)


def _convert(field):
    """Convert one CSV field to a value, per SPEC.md."""
    if field == "":
        return None
    if _INTEGER.match(field):
        try:
            return int(field)
        except ValueError:  # pragma: no cover - regex already guarantees this
            return field
    if _DECIMAL.match(field):
        try:
            return float(field)
        except ValueError:  # pragma: no cover - regex already guarantees this
            return field
    return field


def load_table(directory, name):
    """Load ``<directory>/<name>.csv``, raising ``QueryError`` on failure."""
    path = os.path.join(directory, name + ".csv")
    try:
        stream = open(path, "r", encoding="utf-8", newline="")
    except FileNotFoundError:
        raise QueryError("no such table: %s" % name) from None
    except OSError as exc:
        raise QueryError("cannot read table %s: %s" % (name, exc)) from None

    try:
        with stream:
            reader = csv.reader(stream)
            try:
                headers = next(reader)
            except StopIteration:
                return Table([], [])

            rows = []
            for row in reader:
                # Python's csv module reports a truly blank line as [].  Such
                # lines do not describe a record, so tolerate them.
                if not row:
                    continue
                if len(row) != len(headers):
                    raise QueryError(
                        "%s.csv line %d: expected %d fields, found %d"
                        % (name, reader.line_num, len(headers), len(row))
                    )
                rows.append(tuple(_convert(field) for field in row))
    except csv.Error as exc:
        raise QueryError("%s.csv is not valid CSV: %s" % (name, exc)) from None
    except UnicodeDecodeError as exc:
        raise QueryError("%s.csv is not valid UTF-8: %s" % (name, exc)) from None

    return Table(headers, rows)

"""Execution engine for minisql: turns a parsed SELECT into rows."""

from functools import cmp_to_key

from . import expr
from .ast import Column, Literal, Star, walk
from .errors import QueryError
from .parser import parse
from .table import load_table


class QueryResult:
    """The result of a query: ``columns`` names and ``rows`` tuples."""

    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = [tuple(row) for row in rows]

    def __repr__(self):  # pragma: no cover - debugging convenience
        return "QueryResult(columns=%r, rows=%r)" % (self.columns, self.rows)


def _context(headers, row, group_rows):
    if group_rows is None:
        return expr.EvalContext(headers, row)
    return expr.EvalContext(headers, row, group_rows)


def _validate_columns(node, probe):
    """Raise QueryError for any Column node naming an unknown CSV column."""
    for part in walk(node):
        if isinstance(part, Column):
            probe.resolve(part.name)


def _output_ref_index(node, columns):
    """Return the 0-based output-column index for an ORDER BY item, or -1.

    A bare integer literal is a 1-based output position; a bare Column whose
    name matches an output column case-insensitively refers to that column.
    """
    if isinstance(node, Literal) and type(node.value) is int:
        position = node.value
        if position < 1 or position > len(columns):
            raise QueryError(
                "ORDER BY position %d is out of range (query has %d columns)"
                % (position, len(columns))
            )
        return position - 1
    if isinstance(node, Column):
        folded = node.name.casefold()
        for index, name in enumerate(columns):
            if name.casefold() == folded:
                return index
    return -1


def _compare_null_first(left, right):
    """Compare two sort values with NULL ordering first (ascending)."""
    if left is None:
        return 0 if right is None else -1
    if right is None:
        return 1
    return expr.compare_values(left, right)


def run(sql, directory="."):
    """Parse and execute ``sql`` against CSV files in ``directory``."""
    query = parse(sql)
    table = load_table(directory, query.table)
    headers = list(table.headers)
    rows = list(table.rows)

    probe = expr.EvalContext(headers, (None,) * len(headers))

    # WHERE is evaluated per row and may not use aggregates.
    if query.where is not None:
        expr.validate_no_aggregates(query.where, "WHERE")
        _validate_columns(query.where, probe)

    # GROUP BY expressions are plain expressions; aggregates make no sense here.
    for group_expr in query.group_by:
        expr.validate_no_aggregates(group_expr, "GROUP BY")
        _validate_columns(group_expr, probe)

    if query.having is not None:
        expr.validate_no_nested_aggregates(query.having)
        _validate_columns(query.having, probe)

    # Expand the select list (including *) and determine output names.
    select_items = []  # (expression, output name)
    for item in query.columns:
        if isinstance(item.expr, Star):
            for header in headers:
                node = Column(header)
                node.text = header
                select_items.append((node, header))
            continue

        expr.validate_no_nested_aggregates(item.expr)
        _validate_columns(item.expr, probe)

        if item.alias is not None:
            name = item.alias
        elif isinstance(item.expr, Column):
            name = headers[probe.resolve(item.expr.name)]
        else:
            name = item.expr.text or ""
        select_items.append((item.expr, name))

    output_columns = [name for _node, name in select_items]

    # Classify ORDER BY items before grouped-expression validation: references
    # to output columns are exempt from check_grouped.
    order_specs = []  # (kind, target, descending)
    for item in query.order_by:
        expr.validate_no_nested_aggregates(item.expr)
        index = _output_ref_index(item.expr, output_columns)
        if index >= 0:
            order_specs.append(("output", index, item.desc))
        else:
            _validate_columns(item.expr, probe)
            order_specs.append(("expr", item.expr, item.desc))

    grouped = bool(query.group_by)
    if not grouped:
        grouped = any(expr.contains_aggregate(node) for node, _name in select_items)
    if not grouped and query.having is not None:
        grouped = expr.contains_aggregate(query.having)
    if not grouped:
        grouped = any(
            expr.contains_aggregate(item.expr) for item in query.order_by
        )

    if grouped:
        for select_expr, _name in select_items:
            expr.check_grouped(select_expr, query.group_by)
        if query.having is not None:
            expr.check_grouped(query.having, query.group_by)
        for kind, target, _desc in order_specs:
            if kind == "expr":
                expr.check_grouped(target, query.group_by)

    # WHERE.
    filtered = []
    for row in rows:
        if query.where is None:
            filtered.append(row)
            continue
        context = _context(headers, row, None)
        if expr.evaluate(query.where, context) is True:
            filtered.append(row)

    # Build one unit per output row: (representative row, group rows or None).
    units = []
    if grouped:
        if query.group_by:
            # Preserve first-seen group order.  A plain dict does this on all
            # supported Python versions (3.7+).
            groups = {}
            group_order = []
            for row in filtered:
                context = _context(headers, row, None)
                key = tuple(
                    expr.value_key(expr.evaluate(group_expr, context))
                    for group_expr in query.group_by
                )
                if key not in groups:
                    groups[key] = []
                    group_order.append(key)
                groups[key].append(row)

            for key in group_order:
                group_rows = groups[key]
                representative = group_rows[0]
                context = _context(headers, representative, group_rows)
                if query.having is not None:
                    if expr.evaluate(query.having, context) is not True:
                        continue
                units.append((representative, group_rows))
        else:
            # Without GROUP BY all rows form a single group, even if empty.
            group_rows = list(filtered)
            representative = (
                group_rows[0]
                if group_rows
                else tuple(None for _ in range(len(headers)))
            )
            context = _context(headers, representative, group_rows)
            if query.having is None or expr.evaluate(query.having, context) is True:
                units.append((representative, group_rows))
    else:
        for row in filtered:
            if query.having is not None:
                context = _context(headers, row, None)
                if expr.evaluate(query.having, context) is not True:
                    continue
            units.append((row, None))

    # Projection.  Keep the source row/group so ORDER BY expressions can be
    # evaluated on the row or group that produced each output row.
    entries = []  # [output values, representative row, group rows]
    for representative, group_rows in units:
        context = _context(headers, representative, group_rows)
        values = tuple(
            expr.evaluate(select_expr, context)
            for select_expr, _name in select_items
        )
        entries.append([values, representative, group_rows])

    # DISTINCT keeps the first occurrence, before ordering.
    if query.distinct:
        seen = set()
        distinct_entries = []
        for entry in entries:
            key = tuple(expr.value_key(value) for value in entry[0])
            if key in seen:
                continue
            seen.add(key)
            distinct_entries.append(entry)
        entries = distinct_entries

    # ORDER BY, stable, NULLs first ascending and last descending.
    if order_specs:
        keyed = []
        for entry in entries:
            sort_values = []
            for kind, target, _desc in order_specs:
                if kind == "output":
                    sort_values.append(entry[0][target])
                else:
                    context = _context(headers, entry[1], entry[2])
                    sort_values.append(expr.evaluate(target, context))
            keyed.append((entry, sort_values))

        def compare(left, right):
            for index, (_kind, _target, descending) in enumerate(order_specs):
                result = _compare_null_first(
                    left[1][index], right[1][index]
                )
                if result:
                    return -result if descending else result
            return 0

        keyed.sort(key=cmp_to_key(compare))
        entries = [entry for entry, _values in keyed]

    # OFFSET then LIMIT.
    offset = query.offset or 0
    if offset:
        entries = entries[offset:]
    if query.limit is not None:
        entries = entries[: query.limit]

    return QueryResult(output_columns, [entry[0] for entry in entries])

